import java.io.*;import java.net.ServerSocket;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;import java.util.stream.*;
/** Repeats the official twelve-versus-thirteen piston boundary in fresh worlds. */
public final class PistonPushLimitCycle{
 private static final String ID="m147-piston-push-limit";private final Path root=Paths.get("").toAbsolutePath().normalize(),smoke=root.resolve("smokes").resolve(ID),build=root.resolve(".worldline/smokes").resolve(ID);private final Properties config=new Properties(),artifact=new Properties();
 public static void main(String[]a){if(!Arrays.equals(a,new String[]{ID})){System.err.println("usage: java tools/smoke/PistonPushLimitCycle.java "+ID);System.exit(2);}try{new PistonPushLimitCycle().execute();}catch(Exception e){System.err.println("piston push limit failed: "+e.getMessage());System.exit(1);}}
 private void execute()throws Exception{load(smoke.resolve("smoke.properties"),config);load(root.resolve("artifacts/minecraft-b1.7.3-server.properties"),artifact);require(ID.equals(value(config,"id"))&&value(config,"server.jar.sha256").equals(value(artifact,"expected.sha256")),"descriptor drift");Path official=root.resolve(value(artifact,"local.path")).normalize();verifyArtifact(official);recreate(build);Path classes=compile();Pair first=pair(classes,official,"first"),second=pair(classes,official,"second");require(first.signal.equals(second.signal)&&first.trace.equals(second.trace)&&first.signature.equals(second.signature),"fresh limit pairs diverged");String expected=value(config,"expected.signature");if(expected.equals("pending")||Boolean.getBoolean("worldline.m147.diagnostic")){System.out.println("M147 piston push limit diagnostic passed; qualification not attempted");System.out.println("  "+first.signal);System.out.println("  trace: "+first.trace);System.out.println("  signature: "+first.signature);return;}require(first.signal.equals(value(config,"expected.signal"))&&first.signature.equals(expected),"M147 frozen evidence drift");Files.writeString(build.resolve("evidence.txt"),"id="+ID+"\nservers=4\nclients=8\nfirst="+first.signal+"\nsecond="+second.signal+"\ntrace="+first.trace+"\nsignature="+first.signature+"\n",StandardCharsets.UTF_8);System.out.println("M147 piston push limit passed");System.out.println("  "+first.signal);System.out.println("  signature: "+first.signature);}
 private Pair pair(Path classes,Path official,String name)throws Exception{String capacity=run(classes,official,build.resolve(name+"-12"),value(config,"capacity.blocks")),rejected=run(classes,official,build.resolve(name+"-13"),value(config,"rejected.blocks"));String signal="capacity{"+capacity+"},overlimit{"+rejected+"}",trace="v1|server=official-b1.7.3|seed="+value(config,"seed")+"|fixture=up-piston33+alternating-stone1-cobble4+lever69|settle="+value(config,"fixture.settle.ticks")+"+"+value(config,"signal.settle.ticks")+"ticks|cause=packet15-lever-activate|effect=official-piston-limit-12-accept-13-reject|observation=fresh-login-packet51|"+signal+"|disconnect=clean";return new Pair(signal,trace,sha(trace));}
 private String run(Path classes,Path official,Path workspace,String count)throws Exception{String output=capture(root,Arrays.asList("java","-classpath",classes+separator()+product("api"),"worldline.smoke.pistonlimitb173.PistonPushLimitSmoke",official.toString(),workspace.toString(),Integer.toString(freePort()),value(config,"seed"),value(config,"username")+count,value(config,"target.chunk.x"),value(config,"target.chunk.z"),value(config,"fixture.settle.ticks"),value(config,"signal.settle.ticks"),count));return line(output,"WORLDLINE_M147_COMPONENT=");}
 private Path compile()throws Exception{Path output=build.resolve("adapter-classes");Files.createDirectories(output);List<String>command=new ArrayList<>(Arrays.asList("javac","-encoding","UTF-8","--release","8","-Xlint:all,-options","-Werror","-classpath",product("api").toString(),"-d",output.toString()));command.addAll(javaFiles(root.resolve("adapters/b173-server/src/main/java")));command.addAll(javaFiles(smoke.resolve("src")));capture(root,command);return output;}
 private void verifyArtifact(Path p)throws Exception{require(Files.isRegularFile(p),"server artifact absent");require(Files.size(p)==Long.parseLong(value(artifact,"expected.bytes"))&&digest(p,"SHA-1").equals(value(artifact,"expected.sha1"))&&digest(p,"SHA-256").equals(value(artifact,"expected.sha256")),"server artifact drift");}private List<String>javaFiles(Path s)throws IOException{try(Stream<Path>p=Files.walk(s)){return p.filter(x->x.toString().endsWith(".java")).sorted().map(Path::toString).collect(Collectors.toList());}}private String capture(Path d,List<String>c)throws Exception{Process p=new ProcessBuilder(c).directory(d.toFile()).redirectErrorStream(true).start();String o=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(p.waitFor()!=0)throw new IllegalStateException(c.get(0)+" failed\n"+o);return o;}private void recreate(Path t)throws IOException{if(Files.exists(t)){require(t.startsWith(root.resolve(".worldline"))&&!t.equals(root),"unsafe build path");try(Stream<Path>p=Files.walk(t)){for(Path f:p.sorted(Comparator.reverseOrder()).collect(Collectors.toList()))Files.delete(f);}}Files.createDirectories(t);}private void load(Path p,Properties t)throws IOException{try(Reader r=Files.newBufferedReader(p,StandardCharsets.UTF_8)){t.load(r);}}private String value(Properties p,String k){String v=p.getProperty(k);require(v!=null&&!v.trim().isEmpty(),"missing "+k);return v.trim();}private String digest(Path p,String a)throws Exception{MessageDigest d=MessageDigest.getInstance(a);try(InputStream in=Files.newInputStream(p)){byte[]b=new byte[8192];int n;while((n=in.read(b))>=0)d.update(b,0,n);}return HexFormat.of().formatHex(d.digest());}private String sha(String s)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}private int freePort()throws IOException{try(ServerSocket s=new ServerSocket(0)){return s.getLocalPort();}}private Path product(String n){return root.resolve(".worldline/build/classes").resolve(n);}private String separator(){return System.getProperty("path.separator");}private String line(String o,String p){return o.lines().filter(x->x.startsWith(p)).findFirst().orElseThrow(()->new IllegalStateException("missing "+p+"\n"+o)).substring(p.length());}private static void require(boolean v,String m){if(!v)throw new IllegalStateException(m);}private static final class Pair{final String signal,trace,signature;Pair(String s,String t,String h){signal=s;trace=t;signature=h;}}
}
